# Completa la línea marcada y compruébala con py check.
def valida(salida, campos):
    if not isinstance(salida, dict):
        return False
    for c in campos:
        if c not in salida:
            return False
        # ← añade aquí: el valor tiene que ser un texto (str)
    return True

print(valida({"pedido": "P-101", "problema": "rota", "urgencia": None}, ["pedido", "problema", "urgencia"]))   # False
